const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("chillerState") || {
    kind: "ChillerState",
    version: 1,
    tmsOperatingMode: null,
    outletCoolantTempC: null,
    inletCoolantTempC: null,
    ambientTempC: null,
    inletCoolantPressure: null,
    outletCoolantPressure: null,
    heartbeat: null,
    tmsFaultCode: null,
    tmsFaultLevel: null,
    compressorStatus: null,
    crankcaseHeaterStatus: null,
    electricHeaterStatus: null,
    pumpStatus: null,
    fanRunStatus: null,
    compressorSpeed: null,
    pumpSpeed: null,
    onOffStatus: null
};

function u8(buf, offset) {
    return buf[offset] & 0xFF;
}

function s8(buf, offset) {
    let val = buf[offset] & 0xFF;
    return val > 127 ? val - 256 : val;
}

function getBit(buf, byteOffset, bitOffset) {
    return ((buf[byteOffset] >> bitOffset) & 0x01) === 1;
}

function getBits(buf, byteOffset, bitOffset, length) {
    return (buf[byteOffset] >> bitOffset) & ((1 << length) - 1);
}

var processed = false;

if ((canId & 0xFFFFFFF0) === 0x18008040) {
    processed = true;
    state.tmsOperatingMode = getBits(data, 0, 0, 3);
    state.outletCoolantTempC = u8(data, 1) - 40;
    state.inletCoolantTempC = u8(data, 2) - 40;
    state.ambientTempC = u8(data, 3) - 40;
    state.inletCoolantPressure = s8(data, 4) * 0.1;
    state.outletCoolantPressure = s8(data, 5) * 0.1;
    state.heartbeat = u8(data, 6);
    state.tmsFaultCode = getBits(data, 7, 0, 6);
    state.tmsFaultLevel = getBits(data, 7, 6, 2);
}

if ((canId & 0xFFFFFFF0) === 0x18018040) {
    processed = true;
    state.compressorStatus = getBit(data, 0, 0);
    state.crankcaseHeaterStatus = getBit(data, 0, 1);
    state.electricHeaterStatus = getBit(data, 0, 2);
    state.pumpStatus = getBit(data, 0, 3);
    state.fanRunStatus = getBit(data, 0, 4);
    state.compressorSpeed = u8(data, 1) * 100;
    state.pumpSpeed = u8(data, 2) * 100;
    state.onOffStatus = u8(data, 3);
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("chillerState", state);
msg.payload = state;
return msg;

const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("chillerAlarmState") || {
    kind: "ChillerAlarmState",
    version: 1,
    oICoolantPressSensorFault: null,
    powerSupplyOV: null,
    powerSupplyUV: null,
    systemCoolantShortage: null,
    pumpFaultSummary: null,
    pumpFaultLockSummary: null,
    oCoolantPressSensorFault: null,
    iCoolantPressureSensorFault: null,
    lowPressureSensorFault: null,
    oCoolantTempSensorFault: null,
    systemLowPressureAlarm: null,
    systemHighPressureAlarm: null,
    dischargeTempTooHighAlarm: null,
    canCommunicationFaultAlarm: null,
    suctionTempSensorFault: null,
    coolingSystemAbnormal: null,
    lowSuctionSuperheatDegreeA: null,
    compressorVfdOvAlarm: null,
    compressorVfdUvAlarm: null,
    compressorVfdOcAlarm: null,
    compressorVfdOtAlarm: null,
    compressorVfdComFaultA: null,
    compressorVfdPhaseLossA: null,
    otherCompVfdFaultAlarm: null,
    pumpLowDiffPressAlarm: null,
    dischargeTempTooHighLock: null,
    systemHighPressLock: null,
    systemLowPressLock: null,
    compressorVfdOcLock: null,
    compressorVfdOvLock: null,
    compressorVfdUvLock: null,
    compressorVfdOtLock: null,
    compressorVfdPhsLossLock: null,
    otherCompVfdFaultLocks: null
};

function getBit(buf, bitIndex) {
    const byteIndex = Math.floor(bitIndex / 8);
    const bitOffset = bitIndex % 8;
    if (byteIndex >= buf.length) return false;
    return ((buf[byteIndex] >> bitOffset) & 0x01) === 1;
}

var processed = false;

if ((canId & 0xFFFFFFF0) === 0x18068040) {
    processed = true;
    state.oICoolantPressSensorFault = getBit(data, 0);
    state.powerSupplyOV = getBit(data, 1);
    state.powerSupplyUV = getBit(data, 2);
    state.systemCoolantShortage = getBit(data, 3);
    state.pumpFaultSummary = getBit(data, 4);
    state.pumpFaultLockSummary = getBit(data, 5);
}

if ((canId & 0xFFFFFFF0) === 0x18078040) {
    processed = true;
    state.oCoolantPressSensorFault = getBit(data, 0);
    state.iCoolantPressureSensorFault = getBit(data, 1);
    state.lowPressureSensorFault = getBit(data, 2);
    state.oCoolantTempSensorFault = getBit(data, 3);
    state.systemLowPressureAlarm = getBit(data, 4);
    state.systemHighPressureAlarm = getBit(data, 5);
    state.dischargeTempTooHighAlarm = getBit(data, 6);
    state.canCommunicationFaultAlarm = getBit(data, 7);
    state.suctionTempSensorFault = getBit(data, 8);
    state.coolingSystemAbnormal = getBit(data, 9);
    state.lowSuctionSuperheatDegreeA = getBit(data, 10);
    state.compressorVfdOvAlarm = getBit(data, 11);
    state.compressorVfdUvAlarm = getBit(data, 12);
    state.compressorVfdOcAlarm = getBit(data, 13);
    state.compressorVfdOtAlarm = getBit(data, 14);
    state.compressorVfdComFaultA = getBit(data, 15);
    state.compressorVfdPhaseLossA = getBit(data, 16);
    state.otherCompVfdFaultAlarm = getBit(data, 17);
    state.pumpLowDiffPressAlarm = getBit(data, 18);
    state.dischargeTempTooHighLock = getBit(data, 19);
    state.systemHighPressLock = getBit(data, 20);
    state.systemLowPressLock = getBit(data, 21);
    state.compressorVfdOcLock = getBit(data, 22);
    state.compressorVfdOvLock = getBit(data, 23);
    state.compressorVfdUvLock = getBit(data, 24);
    state.compressorVfdOtLock = getBit(data, 25);
    state.compressorVfdPhsLossLock = getBit(data, 26);
    state.otherCompVfdFaultLocks = getBit(data, 27);
}

if (!processed) {
    return null;
}

const allAlarmFlags = [
    'oICoolantPressSensorFault', 'powerSupplyOV', 'powerSupplyUV',
    'systemCoolantShortage', 'pumpFaultSummary', 'pumpFaultLockSummary',
    'oCoolantPressSensorFault', 'iCoolantPressureSensorFault', 'lowPressureSensorFault',
    'oCoolantTempSensorFault', 'systemLowPressureAlarm', 'systemHighPressureAlarm',
    'dischargeTempTooHighAlarm', 'canCommunicationFaultAlarm', 'suctionTempSensorFault',
    'coolingSystemAbnormal', 'lowSuctionSuperheatDegreeA', 'compressorVfdOvAlarm',
    'compressorVfdUvAlarm', 'compressorVfdOcAlarm', 'compressorVfdOtAlarm',
    'compressorVfdComFaultA', 'compressorVfdPhaseLossA', 'otherCompVfdFaultAlarm',
    'pumpLowDiffPressAlarm', 'dischargeTempTooHighLock', 'systemHighPressLock',
    'systemLowPressLock', 'compressorVfdOcLock', 'compressorVfdOvLock',
    'compressorVfdUvLock', 'compressorVfdOtLock', 'compressorVfdPhsLossLock',
    'otherCompVfdFaultLocks'
];

let activeAlarms = [];
allAlarmFlags.forEach(flag => {
    if (state[flag] === true) activeAlarms.push(flag);
});

state.hasAlarm = activeAlarms.length > 0;
state.activeAlarms = activeAlarms;
state.activeAlarmCount = activeAlarms.length;

state.timestampUtc = new Date().toISOString();
flow.set("chillerAlarmState", state);
msg.payload = state;
return msg;

const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("containerBatteryState") || {
    kind: "ContainerBatteryState",
    version: 1,
    socPercent: null,
    sohPercent: null,
    cycleCount: null,
    remainingEnergyKwh: null,
    availableEnergyKwh: null,
    totalVoltageV: null,
    currentA: null,
    selectedBmuLoc: null,
    selectedCellLoc: null,
    cellVoltageMv: null,
    cellTempC: null,
    maxCellVoltageCellLoc: null,
    maxCellVoltageBmuLoc: null,
    minCellVoltageCellLoc: null,
    minCellVoltageBmuLoc: null,
    avgCellVoltageMv: null,
    maxCellVoltageMv: null,
    minCellVoltageMv: null,
    stateCode: null,
    state: null,
    contactStatusPos: null,
    contactFbkPos: null,
    contactFbkNeg: null,
    chargeComplete: null,
    dischargeComplete: null,
    contactStatusNeg: null,
    isolationStatus: null,
    fuseFbk: null,
    input1Status: null,
    ambientTempC: null,
    dmccA: null,
    dmdcA: null,
    maxCellTempCellLoc: null,
    maxCellTempBmuLoc: null,
    minCellTempCellLoc: null,
    minCellTempBmuLoc: null,
    maxCellTempC: null,
    minCellTempC: null,
    outVoltPosV: null,
    outVoltNegV: null
};

function u8(buf, offset) {
    return buf[offset] & 0xFF;
}

function u16(buf, offset) {
    return (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
}

function getNibbleLow(buf, offset) {
    return buf[offset] & 0x0F;
}

function getNibbleHigh(buf, offset) {
    return (buf[offset] >> 4) & 0x0F;
}

function getBit(buf, byteOffset, bitOffset) {
    return (buf[byteOffset] >> bitOffset) & 0x01;
}

function getBits(buf, byteOffset, bitOffset, length) {
    return (buf[byteOffset] >> bitOffset) & ((1 << length) - 1);
}

const stateMap = {
    0: "N/A",
    101: "Standby",
    102: "Startup",
    103: "Precharge",
    104: "Discharge",
    105: "Charge",
    106: "Shutdown",
    107: "Fault",
    108: "Charge_Complete",
    109: "Discharge_Complete"
};

var processed = false;

if (canId === 0x18FF14F0) {
    processed = true;
    state.socPercent = u8(data, 0);
    state.sohPercent = u8(data, 1);
    state.cycleCount = u16(data, 2);
    state.remainingEnergyKwh = u16(data, 4) * 0.01;
    state.availableEnergyKwh = u16(data, 6) * 0.01;
}

if (canId === 0x18FF11F0) {
    processed = true;
    state.totalVoltageV = u16(data, 0) * 0.1;
    state.currentA = (u16(data, 2) * 0.1) - 1000;
    state.selectedBmuLoc = getNibbleLow(data, 4);
    state.selectedCellLoc = getNibbleHigh(data, 4);
    state.cellVoltageMv = u16(data, 5);
    state.cellTempC = u8(data, 7) - 40;
}

if (canId === 0x18FF12F0) {
    processed = true;
    state.maxCellVoltageCellLoc = getNibbleLow(data, 0);
    state.maxCellVoltageBmuLoc = getNibbleHigh(data, 0);
    state.minCellVoltageCellLoc = getNibbleLow(data, 1);
    state.minCellVoltageBmuLoc = getNibbleHigh(data, 1);
    state.avgCellVoltageMv = u16(data, 2);
    state.maxCellVoltageMv = u16(data, 4);
    state.minCellVoltageMv = u16(data, 6);
}

if (canId === 0x18FF10F0) {
    processed = true;
    state.stateCode = u8(data, 0);
    state.state = stateMap[state.stateCode] || "Unknown";
    state.contactStatusPos = getBit(data, 1, 0);
    state.contactFbkPos = getBit(data, 1, 1);
    state.contactFbkNeg = getBit(data, 1, 2);
    state.chargeComplete = getBit(data, 1, 3) === 1;
    state.dischargeComplete = getBit(data, 1, 4) === 1;
    state.contactStatusNeg = getBit(data, 1, 5);
    state.isolationStatus = getBits(data, 1, 6, 2);
    state.fuseFbk = getBits(data, 2, 0, 2);
    state.input1Status = getBits(data, 2, 2, 2);
    state.ambientTempC = u8(data, 3) - 40;
    state.dmccA = u16(data, 4) * 0.1;
    state.dmdcA = u16(data, 6) * 0.1;
}

if (canId === 0x18FF13F0) {
    processed = true;
    state.maxCellTempCellLoc = getNibbleLow(data, 0);
    state.maxCellTempBmuLoc = getNibbleHigh(data, 0);
    state.minCellTempCellLoc = getNibbleLow(data, 1);
    state.minCellTempBmuLoc = getNibbleHigh(data, 1);
    state.maxCellTempC = u8(data, 2) - 40;
    state.minCellTempC = u8(data, 3) - 40;
    state.outVoltPosV = u16(data, 4) * 0.1;
    state.outVoltNegV = u16(data, 6) * 0.1;
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("containerBatteryState", state);
msg.payload = state;
return msg;

const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

if ((canId & 0xFFFFFFF0) !== 0x18FF2010) {
    return null;
}

function u8(buf, offset) {
    return buf[offset] & 0xFF;
}

function getBit(buf, byteOffset, bitOffset) {
    return ((buf[byteOffset] >> bitOffset) & 0x01) === 1;
}

const stateMap = {
    0: "N/A",
    101: "Standby",
    102: "Startup",
    103: "Precharge",
    104: "Discharge",
    105: "Charge",
    106: "Shutdown"
};

let state = {
    kind: "HVCUControlState",
    version: 1,
    timestampUtc: new Date().toISOString(),
    bcu01ControlStateCode: u8(data, 0),
    bcu01ControlState: stateMap[u8(data, 0)] || "Unknown",
    bcu02ControlStateCode: u8(data, 1),
    bcu02ControlState: stateMap[u8(data, 1)] || "Unknown",
    bcu03ControlStateCode: u8(data, 2),
    bcu03ControlState: stateMap[u8(data, 2)] || "Unknown",
    bcu04ControlStateCode: u8(data, 3),
    bcu04ControlState: stateMap[u8(data, 3)] || "Unknown",
    pack1IsolationControl: getBit(data, 4, 0)
};

flow.set("hvcuControlState", state);
msg.payload = state;
return msg;

